// Print only the self-contained HTML files generated by kit.py.
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

function htmlFiles(folder) {
  return fs.readdirSync(folder, { withFileTypes: true }).flatMap(entry => {
    const file = path.join(folder, entry.name);
    if (entry.isDirectory()) return htmlFiles(file);
    return entry.isFile() && entry.name.endsWith('.html') ? [file] : [];
  });
}

async function printAll(folder) {
  const files = htmlFiles(folder);
  if (!files.length) throw Error('No packet HTML found');
  const executable = process.env.CHROME || (process.platform === 'darwin'
    ? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome' : 'chromium');
  const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'bazi-pilot-pdf-'));
  const browser = spawn(executable, ['--headless=new', '--disable-gpu', '--no-first-run', '--disable-sync',
    '--disable-background-networking', '--remote-debugging-pipe', '--user-data-dir=' + profile, 'about:blank'],
    { stdio: ['ignore', 'ignore', 'ignore', 'pipe', 'pipe'] });
  const pending = new Map();
  let serial = 0;
  let buffer = '';
  function rejectPending(error) {
    for (const job of pending.values()) job.reject(error);
    pending.clear();
  }
  browser.on('error', rejectPending);
  browser.on('exit', () => rejectPending(Error('Chrome exited')));
  browser.stdio[3].on('error', rejectPending);
  browser.stdio[4].setEncoding('utf8');
  browser.stdio[4].on('data', chunk => {
    buffer += chunk;
    let end;
    while ((end = buffer.indexOf('\0')) !== -1) {
      const event = JSON.parse(buffer.slice(0, end));
      buffer = buffer.slice(end + 1);
      const job = pending.get(event.id);
      if (!job) continue;
      pending.delete(event.id);
      if (event.error) job.reject(Error(event.error.message));
      else job.resolve(event.result);
    }
  });
  function call(method, params = {}, sessionId) {
    return new Promise((resolve, reject) => {
      const id = ++serial;
      pending.set(id, { resolve, reject });
      browser.stdio[3].write(JSON.stringify({ id, method, params, sessionId }) + '\0');
    });
  }
  const timer = setTimeout(() => { rejectPending(Error('PDF export timed out')); browser.kill(); }, 240000);
  try {
    const { targetId } = await call('Target.createTarget', { url: 'about:blank' });
    const { sessionId } = await call('Target.attachToTarget', { targetId, flatten: true });
    const send = (method, args) => call(method, args, sessionId);
    await send('Page.enable');
    const { frameTree } = await send('Page.getFrameTree');
    for (const file of files) {
      await send('Page.setDocumentContent', { frameId: frameTree.frame.id, html: fs.readFileSync(file, 'utf8') });
      const ready = await send('Runtime.evaluate', {
        expression: 'Promise.all([document.fonts.ready,...Array.from(document.images, img => img.decode())]).then(()=>true)',
        awaitPromise: true, returnByValue: true
      });
      if (ready.exceptionDetails || ready.result.value !== true) throw Error('Font or image load failed: ' + file);
      const pdf = await send('Page.printToPDF', { printBackground: true, preferCSSPageSize: true, displayHeaderFooter: false });
      fs.writeFileSync(file.slice(0, -5) + '.pdf', Buffer.from(pdf.data, 'base64'));
    }
    console.log('Printed ' + files.length + ' PDFs');
  } finally {
    clearTimeout(timer);
    const closed = new Promise(resolve => {
      if (browser.exitCode !== null || browser.signalCode || !browser.pid) resolve();
      else browser.once('exit', resolve);
    });
    browser.kill();
    await closed;
    fs.rmSync(profile, { recursive: true, force: true, maxRetries: 3 });
  }
}

if (!process.argv[2]) throw Error('Usage: node print.cjs PACKET_DIRECTORY');
printAll(path.resolve(process.argv[2])).catch(error => { console.error(error.message); process.exitCode = 1; });
